import { PostalCodeInput } from '@refy-design/web';
import { useState } from 'react';
function AddressLookup() {
  const [value, setValue] = useState('30140-091');
  const [address, setAddress] = useState('');
  return (
    <div>
      <PostalCodeInput
        value={value}
        onChange={(event) => setValue(event.target.value)}
        lookup={async (postalCode) => {
          await new Promise((resolve) => window.setTimeout(resolve, 600));
          return postalCode === '30140091'
            ? {
                postalCode: '30140-091',
                street: 'Rua Gonçalves Dias',
                neighborhood: 'Employees',
                city: 'Belo Horizonte',
                state: 'MG',
              }
            : null;
        }}
        onAddressFound={(next) =>
          setAddress(
            `${next.street}, ${next.neighborhood}, ${next.city}, ${next.state}`,
          )
        }
      />
      {address && <p>{address}</p>}
    </div>
  );
}
export function Example() {
  return <AddressLookup />;
}

