import { Button } from '@refy-design/web';
import type { PostalCodeAddress } from '@refy-design/web';
import { PostalCodeInput } from '@refy-design/web';
import { useRef } from 'react';
import { useState } from 'react';
export function Example() {
  const [value, setValue] = useState('30140-091');
  const [pending, setPending] = useState(false);
  const complete = useRef<(() => void) | null>(null);
  return (
    <div>
      <PostalCodeInput
        value={value}
        onChange={(event) => setValue(event.target.value)}
        lookup={() =>
          new Promise<PostalCodeAddress | null>((resolve) => {
            setPending(true);
            complete.current = () => {
              resolve({
                postalCode: '30140-091',
                street: 'Sample Street',
                neighborhood: 'Downtown',
                city: 'Belo Horizonte',
                state: 'MG',
              });
              setPending(false);
              complete.current = null;
            };
          })
        }
        onAddressFound={() => {}}
      />
      <Button disabled={!pending} onClick={() => complete.current?.()}>
        Finish simulated lookup
      </Button>
    </div>
  );
}
